&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;8&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;근무시간 : 주 5일 근무 스케줄 근무제 (2회 휴무), 교대 근무&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;gt; A조 &lt;strong&gt;05:00 ~ 14:00&lt;/strong&gt; / B조 &lt;strong&gt;10:00 ~ 19:00&lt;/strong&gt; / C조 &lt;strong&gt;15:00 ~ 24:00&lt;/strong&gt; / D조 &lt;strong&gt;20:00 ~ 05:00&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;(비즈니스 상황에 따라 24시간 이내 스케줄 변경이 있을 수 있음)&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233279&amp;quot;:true,&amp;quot;134245417&amp;quot;:false,&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;전형 절차 및 안내 사항&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233279&amp;quot;:true,&amp;quot;134245417&amp;quot;:false,&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;7&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;전형 절차&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;&lt;/span&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;7&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-olk-copy-source=&quot;MessageBody&quot;&gt;서류전형 - 직무 적합성 인터뷰 - 핵심 역량 인터뷰 – 최종 합격&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;7&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;전형절차는 직무별로 다르게 운영될 수 있으며, 일정 및 상황에 따라 변동될 수 있습니다.&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;7&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;전형 일정 및 결과는 지원서에 등록하신 이메일로 개별 안내 드립니다.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134245417&amp;quot;:false}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;7&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;2&quot; data-aria-level=&quot;1&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;참고 사항&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;&lt;/span&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;7&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;2&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;본 공고는 모집 완료 시 조기 마감될 수 있습니다.&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;7&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;2&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;지원서 내용 중 허위사실이 있는 경우에는 합격이 취소될 수 있습니다.&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;7&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;2&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;취업 보호 대상자(보훈대상자, 장애인 등)는 관련 법률에 따라 채용우대를 받을 수 있습니다.&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;7&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;2&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;직급과 담당 업무 범위는 후보자의 전반적인 경력과 경험 등 제반사정을 고려하여 변경될 수 있습니다. 이러한 변경이 필요할 경우, 최종 합격 통지 전 적절한 시기에 후보자와 커뮤니케이션 될 예정입니다.&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;7&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;2&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;채용 및 업무 수행과 관련하여 요구되는 법령상 자격이 갖추어지지 않은 경우 채용이 제한될 수 있습니다.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134245417&amp;quot;:false}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;7&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;2&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134245417&amp;quot;:false}&quot;&gt;고용형태는 계약직으로 수습기간 12주를 포함합니다. 단, 업무상 필요한 경우에는 상기 수습기간을 적용하지 않거나 단축 또는 연장할 수 있습니다.&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;개인정보 처리방침&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt; &amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134245417&amp;quot;:false}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;12&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;쿠팡 그룹은 입사지원자 개인정보 처리방침(아래 링크)에 따라 귀하의 개인정보를 수집하여 처리합니다. &lt;/span&gt;&lt;a href=&quot;https://www.coupang.jobs/kr/privacy-policy/&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;https://www.coupang.jobs/kr/privacy-policy&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;span data-contrast=&quot;auto&quot;&gt; &amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134245417&amp;quot;:false}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;서류 반환 정책&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt; &lt;span class=&quot;Apple-converted-space&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134245417&amp;quot;:false}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ol&gt;
&lt;li data-leveltext=&quot;%1.&quot; data-font=&quot;&quot; data-listid=&quot;13&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:0,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769242&amp;quot;:[65533,0],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;%1.&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;본&lt;/span&gt;&lt;span class=&quot;Apple-converted-space&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;고지는 『채용절차의공정화에관한법률&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;』&lt;span class=&quot;Apple-converted-space&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;제11조제6항에 따른 것 입니다.&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;%1.&quot; data-font=&quot;&quot; data-listid=&quot;13&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:0,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769242&amp;quot;:[65533,0],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;%1.&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;당사 채용에 응시한 구직자 중 최종 합격이 되지 못한 구직자는 『채용절차의 공정화에 관한 법률』에 따라 제출한 채용서류의 반환을 청구할 수 있음을 알려 드립니다. 다만, 홈페이지 또는 전자우편으로 제출된 경우나 구직자가 당사의 요구 없이 자발적으로 제출한 경우에는 그러하지 아니하며, 천재지변이나 그 밖에 당사에게 책임 없는 사유로 채용서류가 멸실된 경우에는 반환한 것으로 봅니다.&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;%1.&quot; data-font=&quot;&quot; data-listid=&quot;13&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:0,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769242&amp;quot;:[65533,0],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;%1.&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;위2항 본문에 따라 채용 서류 반환 청구를 하는 구직자는 채용 서류 반환 청구서 [채용절차의 공정화에 관한 법률 시행규칙 별지 제 3 호 서식]를 작성하여 이메일 (&lt;/span&gt;&lt;a href=&quot;mailto:recruitingops@coupang.com&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;recruitingops@coupanges.com&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;span data-contrast=&quot;auto&quot;&gt;) 로 제출하면, 제출이 확인된 날로부터 14 일 이내에 지정한 주소지로 등기우편을 통하여 발송해 드립니다. 이 경우 등기우편요금은 수신자 부담으로 하게 되오니 유념하시기 바랍니다. &amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;%1.&quot; data-font=&quot;&quot; data-listid=&quot;13&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:0,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769242&amp;quot;:[65533,0],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;%1.&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;당사는 위2항 본문에 따른 구직자의 반환 청구에 대비하여 채용 여부가 확정된 날로부터 180 일간 구직자가 제출한 채용서류 원본을 보관하게 되며, 그때까지 채용서류의 반환을 청구하지 아니할 경우에는 『개인정보 보호법』에 따라 지체 없이 채용서류 일체를 파기할 예정입니다.&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;%1.&quot; data-font=&quot;&quot; data-listid=&quot;13&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:0,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769242&amp;quot;:[65533,0],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;%1.&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;단, 위 1항 내지 4항의 내용은 대한민국의 노동 관계 법령이 적용되는 경우에만 적용됩니다. 그 이외의 경우에는 적용되지 않습니다.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134245417&amp;quot;:false}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ol&gt;

&lt;p&gt;&lt;strong&gt;회사 소개&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Coupang Fulfillment Services(이하 CFS)는 쿠팡의 물류를 총괄하는 쿠팡의 계열사입니다. CFS는 물류센터(Fulfillment Center, 이하 FC) 운영을 책임지고 있으며, 업무효율성과 전문성 제고를 통해 글로벌 이커머스 기업으로 성장하기 위한 혁신을 이끌어 가고 있습니다.&lt;/p&gt;
&lt;p&gt;Fulfillment Center(이하 FC)는 쿠팡의 물류센터를 말하는 것으로 상품의 입고, 적재, 포장, 출고를 담당하는 곳입니다. FC는 단순한 물류 창고가 아닌, 첨단 기술이 집약된 하나의 Automation Factory로서, 제조업 생산 공장과 같이 각각의 업무를 전문화하고, 입고부터 출고까지 데이터를 기반으로 시공간을 효율적으로 관리하여 낭비를 최소화 하는 등 최적의 물류 시스템을 구현해 나가고 있습니다.&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;직무 소개&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Automation Central Reliability 팀은 Coupang Fulfillment Network 전반의 자동화 설비에 대한 가용성(Availability), 신뢰성(Reliability), 유지보수 효율성(Maintainability) 을 극대화하는 것을 미션으로 합니다.&lt;/p&gt;
&lt;p&gt;본 팀은 물류센터 내 Sorter, Conveyor, Robotics, Control System 등 다양한 자동화 설비를 대상으로,&amp;nbsp;단순 유지보수를 넘어 데이터 기반 신뢰성 엔지니어링과 지속적 개선(Continuous Improvement) 을 수행합니다.&amp;nbsp;특히, 장애 발생 이후 대응하는 방식이 아닌 Failure를 사전에 예측하고 제거하는 Proactive 조직입니다.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;업무 내용&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;설비 신뢰성 전략 수립 및 실행 (Site / Regional Level)&lt;/li&gt;
&lt;li&gt;핵심 설비에 대한 Failure Mode 정의 및 Risk 기반 관리 체계 구축&lt;/li&gt;
&lt;li&gt;Downtime Top Driver에 대한 End-to-End 개선 프로젝트 리딩&lt;/li&gt;
&lt;li&gt;운영 / 엔지니어링 / Safety / Vendor 간 Cross-functional 협업 주도&lt;/li&gt;
&lt;li&gt;Data 기반 의사결정을 통한 OEE 및 Cost 구조 개선&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;자격&lt;/strong&gt; &lt;strong&gt;요건&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;공학 계열 학사 이상 (기계공학, 전기공학, 산업공학 또는 유관 전공) 이신 분&lt;/li&gt;
&lt;li&gt;제조, 물류, 자동화 설비 등 산업 환경에서 10년 이상의 설비/신뢰성/유지보수 관련 경력 보유하신 분&lt;/li&gt;
&lt;li&gt;다음 신뢰성 엔지니어링 기법에 대한 이해 및 실무 경험이 있으신 분
&lt;ul&gt;
&lt;li&gt;RCA (Root Cause Analysis, 근본 원인 분석)&lt;/li&gt;
&lt;li&gt;FMEA (Failure Mode and Effects Analysis, 고장 형태 및 영향 분석)&lt;/li&gt;
&lt;li&gt;RCM (Reliability-Centered Maintenance, 신뢰성 중심 유지보수)&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;설비 유지보수 또는 신뢰성 관리 관련 CMMS 및 자산 관리 시스템 사용 경험이 있으신 분&lt;/li&gt;
&lt;li&gt;다기능 협업 조직(엔지니어링, 운영, 유지보수 등)과의 프로젝트 리딩 및 협업 경험이 있으신 분&lt;/li&gt;
&lt;li&gt;데이터 기반 문제 해결 역량 및 트러블슈팅 능력이 있으신 분&lt;/li&gt;
&lt;li&gt;우수한 커뮤니케이션 및 이해관계자 관리 역량이 있으신 분&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;우대&lt;/strong&gt; &lt;strong&gt;사항&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;신뢰성 관련 전문 자격증 보유하신 분 (예: CRE (Certified Reliability Engineer))&lt;/li&gt;
&lt;li&gt;상태 기반 모니터링 경험이 있으신 분&lt;/li&gt;
&lt;li&gt;Lean, Six Sigma 등 지속적 개선(CI) 방법론 적용 경험이 있으신 분&lt;/li&gt;
&lt;li&gt;자동화 설비 (컨베이어, Sorter, AGV 등) 운영 및 유지보수 경험이 있으신 분&lt;/li&gt;
&lt;li&gt;대규모 물류센터 또는 고가용성 설비 환경에서의 근무 경험이 있으신 분&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;전형 절차 및&lt;/strong&gt;&lt;strong&gt;&amp;nbsp;&lt;/strong&gt;&lt;strong&gt;안내&lt;/strong&gt;&lt;strong&gt;&amp;nbsp;&lt;/strong&gt;&lt;strong&gt;사항&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;전형&lt;/strong&gt;&lt;strong&gt;절차&lt;/strong&gt;
&lt;ul&gt;
&lt;li&gt;서류전형 - &lt;span data-olk-copy-source=&quot;MessageBody&quot;&gt;직무&amp;nbsp;적합성&amp;nbsp;인터뷰&lt;/span&gt; - &lt;span data-olk-copy-source=&quot;MessageBody&quot;&gt;핵심&amp;nbsp;역량&amp;nbsp;인터뷰&lt;/span&gt; – 최종 합격&lt;/li&gt;
&lt;li&gt;전형절차는 직무별로 다르게 운영될 수 있으며, 일정 및 상황에 따라 변동될 수 있습니다.&lt;/li&gt;
&lt;li&gt;전형 일정 및 결과는 지원서에 등록하신 이메일로 개별 안내 드립니다.&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;참고&lt;/strong&gt;&lt;strong&gt;사항&lt;/strong&gt;
&lt;ul&gt;
&lt;li&gt;본 공고는 모집 완료 시 조기 마감될 수 있습니다.&lt;/li&gt;
&lt;li&gt;지원서 내용 중 허위사실이 있는 경우에는 합격이 취소될 수 있습니다.&lt;/li&gt;
&lt;li&gt;취업 보호 대상자(보훈대상자, 장애인 등)는 관련 법률에 따라 채용우대를 받을 수 있습니다.&lt;/li&gt;
&lt;li&gt;직급과 담당 업무 범위는 후보자의 전반적인 경력과 경험 등 제반사정을 고려하여 변경될 수 있습니다. 이러한 변경이 필요할 경우, 최종 합격 통지 전 적절한 시기에 후보자와 커뮤니케이션 될 예정입니다.&lt;/li&gt;
&lt;li&gt;채용 및 업무 수행과 관련하여 요구되는 법령상 자격이 갖추어지지 않은 경우 채용이 제한될 수 있습니다.&lt;/li&gt;
&lt;li&gt;고용형태는 정규직으로 수습기간 12 주를 포함합니다. 단, 업무상 필요한 경우에는 상기 수습기간을 적용하지 않거나 단축 또는 연장할 수 있습니다.&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;개인정보 처리방침&lt;/strong&gt;&amp;nbsp;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;쿠팡 그룹은 입사지원자 개인정보 처리방침(아래 링크)에 따라 귀하의 개인정보를 수집하여 처리합니다.&amp;nbsp;&lt;a href=&quot;https://www.coupang.jobs/kr/privacy-policy/&quot;&gt;https://www.coupang.jobs/kr/privacy-policy/&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;서류&lt;/strong&gt;&lt;strong&gt;&amp;nbsp;&lt;/strong&gt;&lt;strong&gt;반환 정책&lt;/strong&gt;&amp;nbsp;&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;본 고지는 『채용절차의공정화에관한법률』 제11조제6항에 따른 것 입니다.&lt;/li&gt;
&lt;li&gt;당사 채용에 응시한 구직자 중 최종 합격이 되지 못한 구직자는 『채용절차의 공정화에 관한 법률』에 따라 제출한 채용서류의 반환을 청구할 수 있음을 알려 드립니다. 다만, 홈페이지 또는 전자우편으로 제출된 경우나 구직자가 당사의 요구 없이 자발적으로 제출한 경우에는 그러하지 아니하며, 천재지변이나 그 밖에 당사에게 책임 없는 사유로 채용서류가 멸실된 경우에는 반환한 것으로 봅니다.&lt;/li&gt;
&lt;li&gt;위2항 본문에 따라 채용 서류 반환 청구를 하는 구직자는 채용 서류 반환 청구서 [채용절차의 공정화에 관한 법률 시행규칙 별지 제 3 호 서식]를 작성하여 이메일 (&lt;a href=&quot;mailto:recruitingops@coupang.com&quot;&gt;recruitingops@coupangfs.com&lt;/a&gt;) 로 제출하면, 제출이 확인된 날로부터 14 일 이내에 지정한 주소지로 등기우편을 통하여 발송해 드립니다. 이 경우 등기우편요금은 수신자 부담으로 하게 되오니 유념하시기 바랍니다.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;당사는 위2항 본문에 따른 구직자의 반환 청구에 대비하여 채용 여부가 확정된 날로부터 180 일간 구직자가 제출한 채용서류 원본을 보관하게 되며, 그때까지 채용서류의 반환을 청구하지 아니할 경우에는 『개인정보 보호법』에 따라 지체 없이 채용서류 일체를 파기할 예정입니다.&lt;/li&gt;
&lt;li&gt;단, 위 1항 내지 4항의 내용은 대한민국의 노동 관계 법령이 적용되는 경우에만 적용됩니다. 그 이외의 경우에는 적용되지 않습니다.&lt;/li&gt;
&lt;/ol&gt;

&lt;p&gt;&lt;strong&gt;회사 소개&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;CFS (Coupang Fulfillment Services)는 쿠팡의 물류를 총괄하는 쿠팡의 계열사입니다. CFS 는 물류센터 또는 FC (Fulfillment Center) 운영을 책임지고 있으며, 업무 효율성과 전문성 제고를 통해 글로벌 커머스 기업으로 성장하기 위한 혁신을 이끌어 가고 있습니다.&lt;br&gt;쿠팡의 FC 는 상품의 입고, 적재, 포장, 출고 및 반품 등 사후 처리에 이르는 다양한 분야의 전문가들이 함께 일하고 있습니다. FC 는 단순한 물류 창고와 다르게 공장 자동화 (Factory Automation) 솔루션과 첨단 기술을 활용하고 있습니다. 제조업 생산 공장과 같이 각각의 업무를 전문화하고, 입고부터 출고까지 데이터를 기반으로 시공간을 효율적으로 관리하여 낭비를 최소화하는 등 최적의 물류 시스템을 구현해 나가고 있습니다.&lt;br&gt;CFS 는 물류 혁신을 통해 고객이 &quot;쿠팡 없이 어떻게 살았을까?&quot; 라고 말하는 세상을 만들고자 합니다. 우리의 역동적인 미래를 함께 만들고 싶다면 CFS 와 함께하세요.&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;팀 소개&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Health&amp;amp;Wellbeing(H&amp;amp;W)팀은 임직원의 신체적(Physical), 정신적(Mental), 사회적(Social) Wellbeing을 통합적으로 지원하여, 임직원이 건강하고 안전하게 일할 수 있는 환경을 만들어갑니다.&lt;br&gt;임직원들에게 필요한 다양한 건강지원 서비스를 제공하며, 예방적 건강관리와 Wellbeing 활동을 통해 임직원 건강문화를 조성하는 것을 목표로 합니다.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;업무 내용&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;임직원 건강상담 및 맞춤형 건강관리 지원&lt;/li&gt;
&lt;li&gt;응급상황 대응 및 응급처치, 사후 건강관리 수행&lt;/li&gt;
&lt;li&gt;예방 중심의 건강관리 및 건강증진 활동 운영&lt;/li&gt;
&lt;li&gt;건강 데이터 관리, 통계 분석 및 리포팅&lt;/li&gt;
&lt;li&gt;건강위험요인 평가 및 건강한 근무환경 조성 지원&amp;nbsp;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;자격&lt;/strong&gt; &lt;strong&gt;요건&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;간호사 면허를 보유하신 분&lt;/li&gt;
&lt;li&gt;임상현장에서의 건강상담 및 환자 상태평가 역량을 보유하신 분&lt;/li&gt;
&lt;li&gt;응급상황 발생 시 초기 평가 및 응급처치가 가능하신 분&amp;nbsp;&lt;/li&gt;
&lt;li&gt;영어로 외국인 임직원 건강 상담이 가능하신 분&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;우대&lt;/strong&gt; &lt;strong&gt;사항&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;BLS, KALS, ACLS 등 응급처치 관련 자격 또는 교육을 이수하신 분&lt;/li&gt;
&lt;li&gt;건강검진 사후관리 및 건강상담 경험을 보유하신 분&lt;/li&gt;
&lt;li&gt;운전면허증을 소지하신 분&lt;/li&gt;
&lt;li&gt;외국어(영어) 능력을 보유하신 분&amp;nbsp;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;전형 절차 및&lt;/strong&gt;&lt;strong&gt;&amp;nbsp;&lt;/strong&gt;&lt;strong&gt;안내&lt;/strong&gt;&lt;strong&gt;&amp;nbsp;&lt;/strong&gt;&lt;strong&gt;사항&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;전형&lt;/strong&gt;&lt;strong&gt;절차&lt;/strong&gt;
&lt;ul&gt;
&lt;li&gt;서류전형 - 직무 적합성 인터뷰 - 핵심 역량 인터뷰 – 최종 합격&lt;/li&gt;
&lt;li&gt;전형절차는 직무별로 다르게 운영될 수 있으며, 일정 및 상황에 따라 변동될 수 있습니다.&lt;/li&gt;
&lt;li&gt;전형 일정 및 결과는 지원서에 등록하신 이메일로 개별 안내 드립니다.&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;참고&lt;/strong&gt;&lt;strong&gt;사항&lt;/strong&gt;
&lt;ul&gt;
&lt;li&gt;본 공고는 모집 완료 시 조기 마감될 수 있습니다.&lt;/li&gt;
&lt;li&gt;지원서 내용 중 허위사실이 있는 경우에는 합격이 취소될 수 있습니다.&lt;/li&gt;
&lt;li&gt;취업 보호 대상자(보훈대상자, 장애인 등)는 관련 법률에 따라 채용우대를 받을 수 있습니다.&lt;/li&gt;
&lt;li&gt;직급과 담당 업무 범위는 후보자의 전반적인 경력과 경험 등 제반사정을 고려하여 변경될 수 있습니다. 이러한 변경이 필요할 경우, 최종 합격 통지 전 적절한 시기에 후보자와 커뮤니케이션 될 예정입니다.&lt;/li&gt;
&lt;li&gt;채용 및 업무 수행과 관련하여 요구되는 법령상 자격이 갖추어지지 않은 경우 채용이 제한될 수 있습니다.&lt;/li&gt;
&lt;li&gt;고용형태는 정규직으로 수습기간 12 주를 포함합니다. 단, 업무상 필요한 경우에는 상기 수습기간을 적용하지 않거나 단축 또는 연장할 수 있습니다.&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;개인정보 처리방침&lt;/strong&gt;&amp;nbsp;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;쿠팡 그룹은 입사지원자 개인정보 처리방침(아래 링크)에 따라 귀하의 개인정보를 수집하여 처리합니다.&amp;nbsp;&lt;a href=&quot;https://www.coupang.jobs/kr/privacy-policy/&quot;&gt;https://www.coupang.jobs/kr/privacy-policy/&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;서류&lt;/strong&gt;&lt;strong&gt;&amp;nbsp;&lt;/strong&gt;&lt;strong&gt;반환 정책&lt;/strong&gt;&amp;nbsp;&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;본 고지는 『채용절차의공정화에관한법률』 제11조제6항에 따른 것 입니다.&lt;/li&gt;
&lt;li&gt;당사 채용에 응시한 구직자 중 최종 합격이 되지 못한 구직자는 『채용절차의 공정화에 관한 법률』에 따라 제출한 채용서류의 반환을 청구할 수 있음을 알려 드립니다. 다만, 홈페이지 또는 전자우편으로 제출된 경우나 구직자가 당사의 요구 없이 자발적으로 제출한 경우에는 그러하지 아니하며, 천재지변이나 그 밖에 당사에게 책임 없는 사유로 채용서류가 멸실된 경우에는 반환한 것으로 봅니다.&lt;/li&gt;
&lt;li&gt;위2항 본문에 따라 채용 서류 반환 청구를 하는 구직자는 채용 서류 반환 청구서 [채용절차의 공정화에 관한 법률 시행규칙 별지 제 3 호 서식]를 작성하여 이메일 (&lt;a href=&quot;mailto:recruitingops@coupang.com&quot;&gt;recruitingops@coupangfs.com&lt;/a&gt;) 로 제출하면, 제출이 확인된 날로부터 14 일 이내에 지정한 주소지로 등기우편을 통하여 발송해 드립니다. 이 경우 등기우편요금은 수신자 부담으로 하게 되오니 유념하시기 바랍니다.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;당사는 위2항 본문에 따른 구직자의 반환 청구에 대비하여 채용 여부가 확정된 날로부터 180 일간 구직자가 제출한 채용서류 원본을 보관하게 되며, 그때까지 채용서류의 반환을 청구하지 아니할 경우에는 『개인정보 보호법』에 따라 지체 없이 채용서류 일체를 파기할 예정입니다.&lt;/li&gt;
&lt;li&gt;단, 위 1항 내지 4항의 내용은 대한민국의 노동 관계 법령이 적용되는 경우에만 적용됩니다. 그 이외의 경우에는 적용되지 않습니다.&lt;/li&gt;
&lt;/ol&gt;

&lt;p&gt;&lt;strong&gt;회사 소개&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;CFS(Coupang Fulfillment Services)는 쿠팡의 물류를 총괄하는 쿠팡의 계열사입니다. CFS 는 물류센터 또는 FC (Fulfillment Center) 운영을 책임지고 있으며, 업무 효율성과 전문성 제고를 통해 글로벌 커머스 기업으로 성장하기 위한 혁신을 이끌어 가고 있습니다.&lt;/p&gt;
&lt;p&gt;쿠팡의 FC 는 상품의 입고, 적재, 포장, 출고 및 반품 등 사후 처리에 이르는 다양한 분야의 전문가들이 함께 일하고 있습니다. FC 는 단순한 물류 창고와 다르게 공장 자동화(Factory Automation) 솔루션과 첨단 기술을 활용하고 있습니다. 제조업 생산 공장과 같이 각각의 업무를 전문화하고, 입고부터 출고까지 데이터를 기반으로 시공간을 효율적으로 관리하여 낭비를 최소화하는 등 최적의 물류 시스템을 구현해 나가고 있습니다.&lt;/p&gt;
&lt;p&gt;CFS 는 물류 혁신을 통해 고객이 &quot;쿠팡 없이 어떻게 살았을까?&quot; 라고 말하는 세상을 만들고자 합니다. 우리의 역동적인 미래를 함께 만들고 싶다면 CFS 와 함께하세요.&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;직무 소개&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;쿠팡풀필먼트서비스(Coupang Fulfillment Services)의 용인 DIP는 드라이아이스를 생산하는 제조 공장으로, 안정적인 설비 운영을 통해 물류 전반의 품질을 뒷받침합니다. Dry Ice FEM팀은 플랜트 설비 및 유틸리티 관리 전반을 담당하며, 생산 연속성과 설비 신뢰도를 확보하는 핵심 조직입니다. 본 포지션은 FEM팀 매니저로서 전기 안전관리자 법정 선임을 기반으로 플랜트 설비 및 유틸리티 운영을 총괄하고, 유지보수 조직을 리딩합니다. 전기·기계·자동화 설비를 통합적으로 관리하며 공정 효율 개선을 주도하고, 다양한 제조 설비와 공정을 통해 설비 운영 전문성을 확장할 수 있는 기회를 제공합니다.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;업무 내용&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;드라이아이스 제조 공장 내 플랜트 설비 유지보수 및 설비 중요도 평가 수행&lt;/li&gt;
&lt;li&gt;주요 설비 운영 지표 작성 및 분석 관리(MTBF, MTTR 등)&lt;/li&gt;
&lt;li&gt;전기 설비 법정 선임 및 전기 안전관리, 유틸리티 설비 법정 검사 대응&lt;/li&gt;
&lt;li&gt;설비와 공정 개선 활동 수행 및 PLC 프로그램 수정&lt;/li&gt;
&lt;li&gt;공정 내 공사 관리(안전작업허가, 공사 계획 수립, 견적 검토 및 실행 관리)&lt;/li&gt;
&lt;li&gt;정전 및 설비 고장 등 비상 상황 대응 및 원인 분석, 재발 방지 대책 수립&lt;/li&gt;
&lt;li&gt;보전 자재 관리 및 재고 실사, 설비 유지보수 프로세스 및 표준 운영체계 구축&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;자격&lt;/strong&gt; &lt;strong&gt;요건&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;전기산업기사 이상 자격증 보유 및 전기 설비 법정 선임이 가능하신 분&lt;/li&gt;
&lt;li&gt;플랜트 설비 유지보수 및 유압·공압 트러블 대응 경력 8년 이상 보유하신 분&lt;/li&gt;
&lt;li&gt;제조업 기반 사업장에서 냉동기를 포함한 설비 및 유틸리티 운영 경험이 있으신 분&lt;/li&gt;
&lt;li&gt;최소 6명 이상의 팀을 리딩하거나 매니저 역할을 수행한 경험이 있으신 분&lt;/li&gt;
&lt;li&gt;회전기계 및 기계 설비(모터, 펌프 등) 유지보수 및 축정렬 경험이 있으신 분&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;우대&lt;/strong&gt; &lt;strong&gt;사항&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;공조냉동 산업기사 이상 자격증을 보유하신 분&lt;/li&gt;
&lt;li&gt;자동화설비 PLC 통신 및 서보 관련 프로그램 수정 또는 개선 경험이 있으신 분&lt;/li&gt;
&lt;li&gt;AutoCAD를 활용한 도면 수정 및 검토 경험이 있으신 분&lt;/li&gt;
&lt;li&gt;MS Office (Excel, PPT 등) 프로그램 활용한 데이터 분석 및 보고 경험이 있으신 분&lt;/li&gt;
&lt;li&gt;설비 및 공정 개선 프로젝트를 주도적으로 수행하고 성과를 도출한 경험이 있으신 분&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
